payload.script:
$ErrorActionPreference = "Stop"
$WarningPreference = "SilentlyContinue"

try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch { }

$Mode = "{{Mode}}"
$ConfigLanguage = "{{SystemLanguage}}"
$ConfigKeyboards = "{{Keyboards}}"
$LocalizationProfile = "{{LocalizationProfile}}"
$ForceLogoff = "{{ForceLogoff}}" -eq "1"
$LockUserSettings = "{{LockUserSettings}}" -eq "1"
$InstallWatchdog = "{{InstallWatchdog}}" -eq "1"

$profileParts = $LocalizationProfile -split "\|"
if ($profileParts.Count -lt 3) { throw "Invalid LocalizationProfile value: $LocalizationProfile" }
$ConfigLocale = $profileParts[0].Trim()
$ConfigGeoID = [int]$profileParts[1].Trim()
$ConfigTimeZone = $profileParts[2].Trim()
$KeyboardList = @($ConfigKeyboards -split "," | ForEach-Object { $_.Trim() } | Where-Object { $_ })
if ($KeyboardList.Count -eq 0) { $KeyboardList = @("en-US") }
if (@("Audit", "Apply") -notcontains $Mode) { $Mode = "Apply" }

function Add-StepLog {
    param([string]$Message)
    if (-not $script:StepLogs) {
        $script:StepLogs = New-Object System.Collections.ArrayList
    }
    [void]$script:StepLogs.Add("[$(Get-Date -Format 'HH:mm:ss')] $Message")
}

function ConvertTo-PlainObject {
    param($Value)
    if ($null -eq $Value) { return $null }
    if ($Value -is [string] -or $Value -is [bool] -or $Value -is [int] -or $Value -is [long] -or $Value -is [double] -or $Value -is [decimal]) { return $Value }
    if ($Value -is [System.Collections.IDictionary]) {
        $plain = [ordered]@{}
        foreach ($key in $Value.Keys) { $plain[[string]$key] = ConvertTo-PlainObject $Value[$key] }
        return $plain
    }
    if ($Value -is [System.Collections.IEnumerable] -and -not ($Value -is [string])) {
        $items = New-Object System.Collections.ArrayList
        foreach ($item in $Value) { [void]$items.Add((ConvertTo-PlainObject $item)) }
        return ,$items
    }
    $properties = $Value.PSObject.Properties | Where-Object { $_.MemberType -in @("NoteProperty", "Property") -and $_.Name -notmatch "^PS" }
    if ($properties.Count -gt 0) {
        $plain = [ordered]@{}
        foreach ($property in $properties) { $plain[$property.Name] = ConvertTo-PlainObject $property.Value }
        return $plain
    }
    return [string]$Value
}

function Test-UiLanguageInstalled {
    param([string]$LanguageTag)

    $installed = $false
    $method = "none"
    $details = @()
    $userLanguagePresent = $false

    try {
        $cmd = Get-Command Get-InstalledLanguage -ErrorAction SilentlyContinue
        if ($cmd) {
            $langs = @(Get-InstalledLanguage -ErrorAction Stop)
            foreach ($lang in $langs) {
                $id = ""
                foreach ($propertyName in @("LanguageId", "LanguageTag", "Tag")) {
                    $property = $lang.PSObject.Properties[$propertyName]
                    if ($property -and $property.Value) {
                        $id = [string]$property.Value
                        break
                    }
                }
                if ($id -eq $LanguageTag) {
                    $installed = $true
                    $method = "Get-InstalledLanguage"
                    break
                }
            }
            $details += "Get-InstalledLanguage checked"
        }
    } catch {
        $details += "Get-InstalledLanguage failed: $($_.Exception.Message)"
    }

    if (-not $installed) {
        try {
            $muiPath = "HKLM:\SYSTEM\CurrentControlSet\Control\MUI\UILanguages\$LanguageTag"
            if (Test-Path -LiteralPath $muiPath) {
                $installed = $true
                $method = "MUI registry"
            }
            $details += "MUI registry checked"
        } catch {
            $details += "MUI registry check failed: $($_.Exception.Message)"
        }
    }

    try {
        $userLanguagePresent = @((Get-WinUserLanguageList -ErrorAction Stop | ForEach-Object { $_.LanguageTag }) | Where-Object { $_ -eq $LanguageTag }).Count -gt 0
    } catch {
        $details += "Get-WinUserLanguageList check failed: $($_.Exception.Message)"
    }

    [pscustomobject][ordered]@{
        requested = $LanguageTag
        installed = [bool]$installed
        method = $method
        user_language_present = [bool]$userLanguagePresent
        details = @($details)
    }
}
function Get-InstalledUiLanguageInventory {
    $items = @()
    $seen = @{}

    try {
        $cmd = Get-Command Get-InstalledLanguage -ErrorAction SilentlyContinue
        if ($cmd) {
            foreach ($lang in @(Get-InstalledLanguage -ErrorAction Stop)) {
                $id = ""
                foreach ($propertyName in @("LanguageId", "LanguageTag", "Tag")) {
                    $property = $lang.PSObject.Properties[$propertyName]
                    if ($property -and $property.Value) {
                        $id = [string]$property.Value
                        break
                    }
                }
                if ($id -and -not $seen.ContainsKey($id)) {
                    $seen[$id] = $true
                    $items += [pscustomobject][ordered]@{
                        language = $id
                        source = "Get-InstalledLanguage"
                    }
                }
            }
        }
    } catch { }

    try {
        $muiRoot = "HKLM:\SYSTEM\CurrentControlSet\Control\MUI\UILanguages"
        if (Test-Path -LiteralPath $muiRoot) {
            foreach ($key in @(Get-ChildItem -LiteralPath $muiRoot -ErrorAction SilentlyContinue)) {
                $id = [string]$key.PSChildName
                if ($id -and -not $seen.ContainsKey($id)) {
                    $seen[$id] = $true
                    $items += [pscustomobject][ordered]@{
                        language = $id
                        source = "MUI registry"
                    }
                }
            }
        }
    } catch { }

    @($items | Sort-Object language)
}
function Get-CurrentLocalizationState {
    $timeZone = $null
    $culture = $null
    $homeLocation = $null
    $languages = @()
    try { $timeZone = (Get-TimeZone).Id } catch { }
    try { $culture = (Get-Culture).Name } catch { }
    try { $homeLocation = (Get-WinHomeLocation).GeoId } catch { }
    try { $languages = @((Get-WinUserLanguageList | ForEach-Object { $_.LanguageTag })) } catch { }
    [pscustomobject][ordered]@{
        time_zone = $timeZone
        culture = $culture
        home_location_geo_id = $homeLocation
        user_languages = @($languages)
        hkcu_locale = (Get-ItemProperty "HKCU:\Control Panel\International" -Name LocaleName -ErrorAction SilentlyContinue).LocaleName
        hkcu_geo_id = (Get-ItemProperty "HKCU:\Control Panel\International\Geo" -Name Nation -ErrorAction SilentlyContinue).Nation
    }
}

function Set-RegistryValueSafe {
    param([string]$Path, [string]$Name, $Value, [string]$Type = "String")
    if (-not (Test-Path -LiteralPath $Path)) { New-Item -Path $Path -Force | Out-Null }
    New-ItemProperty -Path $Path -Name $Name -Value $Value -PropertyType $Type -Force | Out-Null
}

function Invoke-UserLogoff {
    $loggedOff = @()
    try {
        $sessions = qwinsta 2>&1
        foreach ($line in $sessions) {
            if ($line -match "\b(\d+)\s+(Active|Disc)\b") {
                $id = $matches[1]
                if ($id -ne "0") {
                    logoff $id
                    $loggedOff += $id
                }
            }
        }
    } catch {
        Add-StepLog "User logoff failed: $($_.Exception.Message)"
    }
    return @($loggedOff)
}

$script:StepLogs = New-Object System.Collections.ArrayList
$before = Get-CurrentLocalizationState
$installedUiLanguages = @(Get-InstalledUiLanguageInventory)
$uiLanguagePack = Test-UiLanguageInstalled -LanguageTag $ConfigLanguage
$steps = New-Object System.Collections.ArrayList
$warnings = New-Object System.Collections.ArrayList
$loggedOffSessions = @()
if (-not $uiLanguagePack.installed) {
    [void]$warnings.Add("Requested UI language pack '$ConfigLanguage' is not installed. Region, culture, keyboard and GeoID can be applied, but Windows display language may remain on the currently installed UI language until the language pack is installed.")
}

if ($Mode -eq "Audit") {
    Add-StepLog "Audit mode: no changes will be applied."
    $auditResult = [pscustomobject][ordered]@{
        schema = "winhub.system_localization.v1"
        computer_name = $env:COMPUTERNAME
        checked_at_utc = (Get-Date).ToUniversalTime().ToString("o")
        mode = $Mode
        status = "Audit"
        target = [pscustomobject][ordered]@{
            language = $ConfigLanguage
            locale = $ConfigLocale
            geo_id = $ConfigGeoID
            time_zone = $ConfigTimeZone
            keyboards = @($KeyboardList)
            force_logoff = $ForceLogoff
            lock_user_settings = $LockUserSettings
            install_watchdog = $InstallWatchdog
        }
        ui_language_pack = $uiLanguagePack
        installed_ui_languages = @($installedUiLanguages)
        before = $before
        after = $before
        steps = @("audit")
        step_logs = @($script:StepLogs)
        warnings = @($warnings)
        logged_off_sessions = @()
    }
    ConvertTo-PlainObject $auditResult | ConvertTo-Json -Depth 8 -Compress
    exit 0
}

try {
    Add-StepLog "Target localization: locale=$ConfigLocale geo=$ConfigGeoID timezone=$ConfigTimeZone language=$ConfigLanguage keyboards=$($KeyboardList -join ',')"

    Add-StepLog "Step 1: Remove stale local region policy blocks"
    try { Remove-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer" -Name "SettingsPageVisibility" -ErrorAction SilentlyContinue } catch { }
    try { Remove-Item -Path "HKLM:\SOFTWARE\Policies\Microsoft\Control Panel\International" -Recurse -Force -ErrorAction SilentlyContinue } catch { }
    [void]$steps.Add("stale_policy_cleanup")

    Add-StepLog "Step 2: Set time zone"
    try { Set-TimeZone -Id $ConfigTimeZone -ErrorAction Stop; [void]$steps.Add("time_zone") } catch { [void]$warnings.Add("Set-TimeZone failed: $($_.Exception.Message)") }

    Add-StepLog "Step 3: Set current user language list, culture and home location"
    try { Set-WinUserLanguageList -LanguageList $KeyboardList -Force -ErrorAction Stop; [void]$steps.Add("user_language_list") } catch { [void]$warnings.Add("Set-WinUserLanguageList failed: $($_.Exception.Message)") }
    try { Set-Culture -CultureInfo $ConfigLocale -ErrorAction Stop; [void]$steps.Add("culture") } catch { [void]$warnings.Add("Set-Culture failed: $($_.Exception.Message)") }
    try { Set-WinHomeLocation -GeoId $ConfigGeoID -ErrorAction Stop; [void]$steps.Add("home_location") } catch { [void]$warnings.Add("Set-WinHomeLocation failed: $($_.Exception.Message)") }
    try { Set-RegistryValueSafe -Path "HKCU:\Control Panel\Desktop" -Name "PreferredUILanguages" -Value $ConfigLanguage; [void]$steps.Add("preferred_ui_language") } catch { [void]$warnings.Add("Preferred UI language failed: $($_.Exception.Message)") }

    Add-StepLog "Step 4: Disable RDP keyboard/time zone redirection overrides"
    try {
        Set-RegistryValueSafe -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Keyboard Layout" -Name "IgnoreRemoteKeyboardLayout" -Value 1 -Type "DWord"
        Set-RegistryValueSafe -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\Terminal Services" -Name "fEnableTimeZoneRedirection" -Value 0 -Type "DWord"
        [void]$steps.Add("rdp_redirection_policy")
    } catch { [void]$warnings.Add("RDP policy update failed: $($_.Exception.Message)") }

    Add-StepLog "Step 5: Set default profile and welcome screen values"
    try {
        Set-RegistryValueSafe -Path "Registry::HKEY_USERS\.DEFAULT\Control Panel\International" -Name "LocaleName" -Value $ConfigLocale
        Set-RegistryValueSafe -Path "Registry::HKEY_USERS\.DEFAULT\Control Panel\International\Geo" -Name "Nation" -Value $ConfigGeoID
        Set-RegistryValueSafe -Path "Registry::HKEY_USERS\.DEFAULT\Control Panel\Desktop" -Name "PreferredUILanguages" -Value $ConfigLanguage
        [void]$steps.Add("default_profile_registry")
    } catch { [void]$warnings.Add("Default profile registry update failed: $($_.Exception.Message)") }

    Add-StepLog "Step 6: Apply intl.cpl globalization XML"
    $xmlPath = Join-Path $env:ProgramData "WinHUB_ForceLocale.xml"
    $xmlContent = @"
<gs:GlobalizationServices xmlns:gs="urn:longhornGlobalizationUnattend">
  <gs:UserList>
    <gs:User UserID="Current" CopySettingsToDefaultUserAcct="true" CopySettingsToSystemAcct="true"/>
  </gs:UserList>
  <gs:UILanguage><gs:Language Value="$ConfigLanguage" SetAsCurrent="true"/></gs:UILanguage>
  <gs:SystemLocale><gs:Locale Name="$ConfigLanguage"/></gs:SystemLocale>
  <gs:UserLocale><gs:Locale Name="$ConfigLocale" SetAsCurrent="true"/></gs:UserLocale>
  <gs:LocationPreferences><gs:GeoID Value="$ConfigGeoID"/></gs:LocationPreferences>
</gs:GlobalizationServices>
"@
    try {
        $xmlContent | Out-File -FilePath $xmlPath -Encoding UTF8 -Force
        Start-Process -FilePath "control.exe" -ArgumentList "intl.cpl,,/f:`"$xmlPath`"" -Wait -WindowStyle Hidden
        [void]$steps.Add("globalization_xml")
    } catch { [void]$warnings.Add("intl.cpl XML apply failed: $($_.Exception.Message)") }

    if ($LockUserSettings -or $InstallWatchdog) {
        Add-StepLog "Step 7: Generate per-user startup watchdog"
        $langArrayLiteral = ($KeyboardList | ForEach-Object { "'$($_)'" }) -join ","
        $watchdogPath = Join-Path $env:ProgramData "SetTerminalLocale.ps1"
        $watchdog = @"
`$ErrorActionPreference = 'SilentlyContinue'
`$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
`$hkcuExplorer = 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer'
`$hkcuPolInt = 'HKCU:\SOFTWARE\Policies\Microsoft\Control Panel\International'
if ('$LockUserSettings' -eq 'True' -and -not `$isAdmin) {
    if (-not (Test-Path `$hkcuExplorer)) { New-Item -Path `$hkcuExplorer -Force | Out-Null }
    if (-not (Test-Path `$hkcuPolInt)) { New-Item -Path `$hkcuPolInt -Force | Out-Null }
    Set-ItemProperty -Path `$hkcuExplorer -Name 'SettingsPageVisibility' -Value 'hide:timeandlanguage;dateandtime;region;language;regionlanguage;regionformatting' -Type String -Force
    Set-ItemProperty -Path `$hkcuPolInt -Name 'BlockUserLocale' -Value 1 -Type DWord -Force
    Set-ItemProperty -Path `$hkcuPolInt -Name 'BlockUserUILanguage' -Value 1 -Type DWord -Force
    if (-not (Test-Path "`$hkcuExplorer\DisallowCpl")) { New-Item -Path "`$hkcuExplorer\DisallowCpl" -Force | Out-Null }
    Set-ItemProperty -Path `$hkcuExplorer -Name 'DisallowCpl' -Value 1 -Type DWord -Force
    Set-ItemProperty -Path "`$hkcuExplorer\DisallowCpl" -Name '1' -Value 'intl.cpl' -Type String -Force
    Set-ItemProperty -Path "`$hkcuExplorer\DisallowCpl" -Name '2' -Value 'timedate.cpl' -Type String -Force
}
Set-WinUserLanguageList -LanguageList $langArrayLiteral -Force
Set-Culture -CultureInfo '$ConfigLocale'
Set-WinHomeLocation -GeoId $ConfigGeoID
Set-ItemProperty -Path 'HKCU:\Control Panel\Desktop' -Name 'PreferredUILanguages' -Value '$ConfigLanguage' -Force
`$end = (Get-Date).AddMinutes(3)
while ((Get-Date) -lt `$end) {
    `$currentLocale = (Get-ItemProperty 'HKCU:\Control Panel\International' -Name LocaleName -ErrorAction SilentlyContinue).LocaleName
    `$currentGeo = (Get-ItemProperty 'HKCU:\Control Panel\International\Geo' -Name Nation -ErrorAction SilentlyContinue).Nation
    if (`$currentLocale -ne '$ConfigLocale' -or `$currentGeo -ne '$ConfigGeoID') {
        Set-ItemProperty -Path 'HKCU:\Control Panel\International' -Name 'LocaleName' -Value '$ConfigLocale' -Force
        Set-ItemProperty -Path 'HKCU:\Control Panel\International\Geo' -Name 'Nation' -Value '$ConfigGeoID' -Force
        Set-WinUserLanguageList -LanguageList $langArrayLiteral -Force
        Set-Culture -CultureInfo '$ConfigLocale'
        Set-WinHomeLocation -GeoId $ConfigGeoID
    }
    Start-Sleep -Seconds 2
}
"@
        try {
            $watchdog | Out-File -FilePath $watchdogPath -Encoding UTF8 -Force
            $startupFolder = Join-Path $env:ProgramData "Microsoft\Windows\Start Menu\Programs\StartUp"
            if (-not (Test-Path -LiteralPath $startupFolder)) { New-Item -Path $startupFolder -ItemType Directory -Force | Out-Null }
            $vbsPath = Join-Path $startupFolder "ApplyLocaleConfig.vbs"
            $vbs = "Set objShell = CreateObject(`"WScript.Shell`")`r`nobjShell.Run `"powershell.exe -ExecutionPolicy Bypass -WindowStyle Hidden -NoProfile -File `"`"$watchdogPath`"`"`", 0, False"
            $vbs | Out-File -FilePath $vbsPath -Encoding ASCII -Force
            [void]$steps.Add("startup_watchdog")
        } catch { [void]$warnings.Add("Watchdog generation failed: $($_.Exception.Message)") }
    }

    if ($ForceLogoff) {
        Add-StepLog "Step 8: Log off active/disconnected user sessions"
        $loggedOffSessions = @(Invoke-UserLogoff)
        [void]$steps.Add("user_logoff")
    }

    $after = Get-CurrentLocalizationState
    $coreApplied = (
        $after.time_zone -eq $ConfigTimeZone -and
        [string]$after.home_location_geo_id -eq [string]$ConfigGeoID -and
        [string]$after.hkcu_locale -eq [string]$ConfigLocale
    )
    if ($coreApplied -and $after.culture -ne $ConfigLocale) {
        [void]$warnings.Add("Current process culture still reports '$($after.culture)'. Windows may finish applying display/culture changes after the next sign-in.")
    }
    $success = $coreApplied
    $status = if ($success -and $warnings.Count -eq 0) { "Applied" } elseif ($success) { "Applied with warnings" } else { "Completed with drift" }

    $result = [pscustomobject][ordered]@{
        schema = "winhub.system_localization.v1"
        computer_name = $env:COMPUTERNAME
        checked_at_utc = (Get-Date).ToUniversalTime().ToString("o")
        mode = $Mode
        status = $status
        target = [pscustomobject][ordered]@{
            language = $ConfigLanguage
            locale = $ConfigLocale
            geo_id = $ConfigGeoID
            time_zone = $ConfigTimeZone
            keyboards = @($KeyboardList)
            force_logoff = $ForceLogoff
            lock_user_settings = $LockUserSettings
            install_watchdog = $InstallWatchdog
        }
        ui_language_pack = $uiLanguagePack
        installed_ui_languages = @($installedUiLanguages)
        before = $before
        after = $after
        steps = @($steps)
        step_logs = @($script:StepLogs)
        warnings = @($warnings)
        logged_off_sessions = @($loggedOffSessions)
    }

    ConvertTo-PlainObject $result | ConvertTo-Json -Depth 8 -Compress
    if (-not $success) { exit 2 }
}
catch {
    $errorResult = [pscustomobject][ordered]@{
        schema = "winhub.system_localization.v1"
        computer_name = $env:COMPUTERNAME
        checked_at_utc = (Get-Date).ToUniversalTime().ToString("o")
        mode = $Mode
        status = "Script error"
        target = [pscustomobject][ordered]@{ locale = $ConfigLocale; geo_id = $ConfigGeoID; time_zone = $ConfigTimeZone; language = $ConfigLanguage; keyboards = @($KeyboardList) }
        ui_language_pack = $uiLanguagePack
        installed_ui_languages = @($installedUiLanguages)
        before = $before
        after = Get-CurrentLocalizationState
        steps = @($steps)
        step_logs = @($script:StepLogs)
        warnings = @($warnings)
        error = $_.Exception.Message
    }
    ConvertTo-PlainObject $errorResult | ConvertTo-Json -Depth 8 -Compress
    exit 1
}

[[WINHUB_REPORT title="System Localization Report"]]
