{% for r in results -%}
{% if r.status != 'Success' -%}
{% set ns.failed = ns.failed + 1 -%}
{% elif not r.data -%}
{% set ns.unparsed = ns.unparsed + 1 -%}
{% elif r.data.status == 'Audit' -%}
{% set ns.audit = ns.audit + 1 -%}
{% elif r.data.status == 'Applied' -%}
{% set ns.applied = ns.applied + 1 -%}
{% elif r.data.status == 'Applied with warnings' -%}
{% set ns.warning = ns.warning + 1 -%}
{% else -%}
{% set ns.drift = ns.drift + 1 -%}
{% endif -%}
{% endfor %}
Localization report: {{ job_title }}

SUMMARY
- Total endpoints: {{ results|length }}
- Applied: {{ ns.applied }}
- Applied with warnings: {{ ns.warning }}
- Completed with drift: {{ ns.drift }}
- Task failures: {{ ns.failed }}
- Unparsed success outputs: {{ ns.unparsed }}
- Audit only: {{ ns.audit }}

TARGETS
{% for r in results if r.status == 'Success' and r.data -%}
- {{ r.host }} | {{ r.data.status or '-' }} | mode={{ r.data.mode or 'Apply' }} | target {{ r.data.target.locale or '-' }} / GeoID {{ r.data.target.geo_id or '-' }} / {{ r.data.target.time_zone or '-' }} | UI pack {{ 'installed' if r.data.ui_language_pack and r.data.ui_language_pack.installed else 'missing' }} | keyboards: {{ r.data.target.keyboards|join(', ') if r.data.target.keyboards else '-' }} | logoff: {{ 'not executed in audit' if r.data.status == 'Audit' else r.data.target.force_logoff }}
{% else -%}
- none
{% endfor %}

WARNINGS AND DRIFT
