- {{ r.host }} | {{ r.data.status or '-' }}
  Before: culture={{ r.data.before.culture or '-' }}, timezone={{ r.data.before.time_zone or '-' }}, geo={{ r.data.before.home_location_geo_id or '-' }}
  After: culture={{ r.data.after.culture or '-' }}, timezone={{ r.data.after.time_zone or '-' }}, geo={{ r.data.after.home_location_geo_id or '-' }}
{% if r.data.warnings is string %}
  - {{ r.data.warnings }}
{% else %}
{% for item in r.data.warnings if item %}
  - {{ item }}
{% endfor %}
{% endif %}
{% else -%}
- none
{% endfor %}

AUDIT SNAPSHOT
