- {{ r.host }} | culture={{ r.data.before.culture or '-' }} | HKCU locale={{ r.data.before.hkcu_locale or '-' }} | timezone={{ r.data.before.time_zone or '-' }} | GeoID={{ r.data.before.home_location_geo_id or '-' }} | UI languages={{ r.data.installed_ui_languages|map(attribute='language')|join(', ') if r.data.installed_ui_languages else '-' }} | user languages={{ r.data.before.user_languages|join(', ') if r.data.before.user_languages else '-' }}
{% else -%}
- none
{% endfor %}

LOGOFF
{% for r in results if r.status == 'Success' and r.data and r.data.logged_off_sessions -%}
- {{ r.host }} | sessions: {{ r.data.logged_off_sessions|join(', ') if r.data.logged_off_sessions else '-' }}
{% else -%}
- none
{% endfor %}

TASK FAILURES
{% for r in results if r.status != 'Success' -%}
- {{ r.host }} | {{ r.status }} | {{ r.log }}
{% else -%}
